#!/bin/bash
# GENERATED by scripts/gen_agent_trees.py from agent/guards/adapters/claude/backup-before-edit.sh. Toolkit contributors: edit the source; setup.sh configures this installed copy.
# Claude Code adapter for skyguard's pre-edit backup. The logic lives in tools/skyguard/backup.py;
# this wrapper reads the payload, records the heartbeat and runs the engine.
#
# SETUP: setup.sh fills in the Python path below (it writes sys.executable of the Python it found).
#
# This hook never blocks. It is the record that makes a bad edit recoverable, so a failure here must
# be LOUD in the audit log rather than a silent no-op.
#
# A bare `cat`, never `cat /dev/stdin`: the latter returns ZERO BYTES when Claude Code (Node) spawns a
# hook, which made every hook here inert for five weeks. tools/hook-canary.sh reads the heartbeat.

HOOK_NAME="backup-before-edit"
PY="{{PYTHON_PATH}}"
INPUT=$(cat)

_SELF="${BASH_SOURCE[0]//\//}"
HOOK_DIR="$(cd "$(dirname "$_SELF")" 2>/dev/null && pwd)"
ROOT="$(cd "$HOOK_DIR/../.." 2>/dev/null && pwd)"
ROOT_WIN="$(cd "$HOOK_DIR/../.." 2>/dev/null && pwd -W 2>/dev/null)"
PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$ROOT}"
BACKUP_DIR="$PROJECT_DIR/.claude/backups"
AUDIT_LOG="$BACKUP_DIR/AUDIT_LOG.txt"
HB_DIR="$BACKUP_DIR/.hook-heartbeat"
mkdir -p "$HB_DIR" 2>/dev/null

if ! command -v "$PY" >/dev/null 2>&1; then
    printf '[%s] %s FAILED: Python not runnable (%s) -- NO backup/snapshot was taken\n' \
        "$(date +%Y%m%d_%H%M%S)" "$HOOK_NAME" "$(printf '%s' "$PY" | tr '\134' '/')" >> "$AUDIT_LOG" 2>/dev/null
    exit 0
fi

if [ -n "$INPUT" ]; then
    printf '%s payload_bytes=%s\n' "$(date +%Y%m%d_%H%M%S)" "${#INPUT}" > "$HB_DIR/$HOOK_NAME" 2>/dev/null
else
    printf '%s NO PAYLOAD\n' "$(date +%Y%m%d_%H%M%S)" > "$HB_DIR/$HOOK_NAME.blind" 2>/dev/null
fi

printf '%s' "$INPUT" | "$PY" "${ROOT_WIN:-$ROOT}/tools/skyguard/run.py" claude "$HOOK_NAME" \
    --root "$ROOT" --root-win "$ROOT_WIN" --project "$PROJECT_DIR" >/dev/null 2>&1
RC=$?
if [ "$RC" -ne 0 ]; then
    printf '[%s] %s FAILED: engine error (exit %s) -- NO backup/snapshot was taken\n' \
        "$(date +%Y%m%d_%H%M%S)" "$HOOK_NAME" "$RC" >> "$AUDIT_LOG" 2>/dev/null
fi
exit 0
